export type Listener<T> = (data: T) => void;

export class TypedEventBus<EventMap extends Record<string, any>> {
  private listeners: Map<keyof EventMap, Set<Listener<any>>> = new Map();

  public on<E extends keyof EventMap>(event: E, listener: Listener<EventMap[E]>): () => void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }
    this.listeners.get(event)!.add(listener);
    return () => this.off(event, listener);
  }

  public off<E extends keyof EventMap>(event: E, listener: Listener<EventMap[E]>): void {
    const set = this.listeners.get(event);
    if (set) {
      set.delete(listener);
      if (set.size === 0) {
        this.listeners.delete(event);
      }
    }
  }

  public emit<E extends keyof EventMap>(event: E, data: EventMap[E]): void {
    const set = this.listeners.get(event);
    if (set) {
      for (const listener of Array.from(set)) {
        listener(data);
      }
    }
  }

  public listenerCount<E extends keyof EventMap>(event: E): number {
    return this.listeners.get(event)?.size ?? 0;
  }
}

