interface AppEvents {
  'user:login': { userId: string; timestamp: number };
  'cart:checkout': { amount: number };
}

const bus = new TypedEventBus<AppEvents>();
let received = '';
const unsub = bus.on('user:login', (data) => {
  received = data.userId;
});
console.assert(bus.listenerCount('user:login') === 1);
bus.emit('user:login', { userId: 'user_42', timestamp: Date.now() });
console.assert(received === 'user_42');
unsub();
console.assert(bus.listenerCount('user:login') === 0);
console.log('TS_EVENT_BUS_SUCCESS');
